mapper.select:
SELECT source_document_id, ref_id, resource_node_id, is_delete
FROM biz_document_relation
WHERE source_document_id = #{sourceDocumentId}
  AND ref_id = #{refId}

mapper.update:
UPDATE biz_document_relation
SET resource_node_id = #{resourceNodeId},
    is_delete = 0
WHERE source_document_id = #{sourceDocumentId}
  AND ref_id = #{refId}

UPDATE biz_document_relation
SET is_delete = 1
WHERE source_document_id = #{sourceDocumentId}
  AND ref_id = #{refId}
  AND is_delete = 0
